INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q974160', 'Cudgel War', 'The Cudgel War (also known as the Club War; Finnish: Nuijasota; Swedish: Klubbekriget) was a 1596–1597 peasant uprising in Finland, which was then part of the Kingdom of Sweden. The name of the uprising derives from the fact that the peasants armed themselves with various blunt weapons, such as cudgels, flails, and maces, since they were seen as the most efficient weapons against their heavily armoured enemies.', 1596, 11, 25, 1597, NULL, NULL, 'day', '25 November 1596 – 1597', 59, 'https://en.wikipedia.org/wiki/Cudgel_War'),
  ('Q694122', 'Battle of Napue', 'The Battle of Napue, the Battle of Isokyrö (Storkyro), or the Battle of Lappola was fought on 2 March [O.S. 19 February] 1714 at the villages of Napue and Laurola, located in the Isokyrö parish of the Swedish Empire (modern-day Finland). The battle took place between the Swedish Empire and the Tsardom of Russia and was the final land battle of the Finnish campaign in the Great Northern War.', 1714, 3, 2, NULL, NULL, NULL, 'day', '2 March 1714', 50, 'https://en.wikipedia.org/wiki/Battle_of_Napue'),
  ('Q682482', 'Russo-Swedish War of 1741-1743', 'The Russo-Swedish War of 1741–1743 (also known as The War of the Hats or The Hats'' war) was instigated by the Hats, a Swedish political party that aspired to regain the territories lost to Russia during the Great Northern War, and by French diplomacy, which sought to divert Russia''s attention from supporting its long-standing ally the Habsburg monarchy in the War of the Austrian Succession. The war was a disaster for Sweden, which lost more territory to Russia.', 1741, NULL, NULL, 1743, NULL, NULL, 'year', '1741–1743', 64, 'https://en.wikipedia.org/wiki/Russo-Swedish_War_(1741%E2%80%931743)'),
  ('Q2890333', 'Battle of Villmanstrand', 'The Battle of Villmanstrand, also referred to as the storming of Villmanstrand, was fought during the Russo-Swedish War on 3 September 1741, when Russian forces of 10,000 men (13,000, or 16,000–18,000, according to Swedish estimates), under the command of General Peter von Lacy, assaulted the fortress of Villmanstrand (Finnish: Lappeenranta). Lacy drawn up in 2 storming lines: the 1st (grenadier and 4 infantry regiments) was commanded by General Fyodor Stoffeln, the 2nd (5 infantry regiments and all cavalry) by General Ivan Bakhmetev.', 1741, 8, 23, NULL, NULL, NULL, 'day', '23 August 1741', 37, 'https://en.wikipedia.org/wiki/Battle_of_Villmanstrand'),
  ('Q8096173', 'Lesser Wrath', 'The Russo-Swedish War of 1741–1743 (also known as The War of the Hats or The Hats'' war) was instigated by the Hats, a Swedish political party that aspired to regain the territories lost to Russia during the Great Northern War, and by French diplomacy, which sought to divert Russia''s attention from supporting its long-standing ally the Habsburg monarchy in the War of the Austrian Succession. The war was a disaster for Sweden, which lost more territory to Russia.', 1741, NULL, NULL, 1743, NULL, NULL, 'year', '1741–1743', 30, 'https://en.wikipedia.org/wiki/Lesser_Wrath'),
  ('Q4871066', 'Battle of Fredrikshamn', 'The battle of Fredrikshamn was an attack by the Swedish archipelago fleet on their Russian counterparts near the town of Fredrikshamn (Hamina) during the Russo-Swedish War (1788–1790).', 1790, 5, 15, NULL, NULL, NULL, 'day', '15 May 1790', 34, 'https://en.wikipedia.org/wiki/Battle_of_Fredrikshamn'),
  ('Q2441248', 'Anglo-Russian War', 'The Anglo-Russian War (2 September 1807 – 18 July 1812) was fought between the United Kingdom and the Russian Empire during the Napoleonic Wars. It began after Russia signed the Treaty of Tilsit with the First French Empire, which ended hostilities between the two nations.', 1807, 9, 2, 1812, 7, 18, 'day', '2 September 1807 – 18 July 1812', 57, 'https://en.wikipedia.org/wiki/Anglo-Russian_War_(1807%E2%80%931812)'),
  ('Q736268', 'Finnish War', 'The Finnish War was fought between the Kingdom of Sweden and the Russian Empire from 21 February 1808 to 17 September 1809 as part of the Napoleonic Wars. As a result of the war, the eastern third of Sweden was established as the autonomous Grand Duchy of Finland within the Russian Empire.', 1808, 2, 21, 1809, 9, 17, 'day', '21 February 1808 – 17 September 1809', 73, 'https://en.wikipedia.org/wiki/Finnish_War'),
  ('Q2182031', 'Battle of Siikajoki', 'The Battle of Siikajoki (Finnish: Siikajoen taistelu) was fought between Swedish and Russian troops on 18 April 1808 at Siikajoki, approximately 60 km south of Uleåborg, Swedish Finland (today Oulu, Republic of Finland). During the first stage of the Finnish War, the Swedish commander Wilhelm Mauritz Klingspor had decided to retreat from southern Finland, so that the Swedes would gain time, and more troops could be moved to Finland via Tornio.', 1808, 4, 18, NULL, NULL, NULL, 'day', '18 April 1808', 41, 'https://en.wikipedia.org/wiki/Battle_of_Siikajoki'),
  ('Q2562633', 'Battle of Lemo', 'The Battle of Lemo was fought during the Finnish War between Sweden and Russia on 19–20 June 1808 (Julian calendar 7–8 June). On 19 June, about 2,500 Swedes landed at Lemo (Finnish:Lemu) in Kaarina (Swedish:S:t Karins) in Southwest Finland, aided by the Swedish Navy.', 1808, 6, 19, 1808, 6, 20, 'day', '19 June 1808 – 20 June 1808', 34, 'https://en.wikipedia.org/wiki/Battle_of_Lemo'),
  ('Q2599254', 'Battle of Alavus', 'The Battle of Alavus took place on 17 August 1808 in the vicinity of the town of Alavus (Swedish: Alavo), as part of the Finnish War. The Finnish army, under the command of General Carl Johan Adlercreutz defeated a smaller Russian force and drove it southwards.', 1808, 8, 17, NULL, NULL, NULL, 'day', '17 August 1808', 37, 'https://en.wikipedia.org/wiki/Battle_of_Alavus'),
  ('Q2600573', 'Siege of Sveaborg', 'The siege of Sveaborg was a siege by Imperial Russian forces of the sea fort of Sveaborg (Finnish: Suomenlinna), off the coast of Helsingfors (Helsinki); at the time Finland was part of the Kingdom of Sweden. It took place in the spring of 1808, during the Finnish War.', 1808, 3, 2, 1808, 5, 3, 'day', '2 March 1808 – 3 May 1808', 37, 'https://en.wikipedia.org/wiki/Siege_of_Sveaborg'),
  ('Q2600584', 'Battle of Lapua', 'The Battle of Lapua was fought between Swedish and Russian troops on 14 July 1808 at Lapua, Finland. The battle was a part of the Finnish War of 1808–1809.', 1808, 7, 14, NULL, NULL, NULL, 'day', '14 July 1808', 37, 'https://en.wikipedia.org/wiki/Battle_of_Lapua'),
  ('Q2638217', 'Battle of Koljonvirta', 'The Battle of Koljonvirta (Finnish: Koljonvirran taistelu, Swedish: Slaget vid Virta bro) i.e. the Battle of the Virta Bridge, also known as the battle of Idensalmi (Russian: Иденсальмское сражение), was fought between Swedish and Russian troops on October 27, 1808, in the course of Finnish War, with the Swedes prevailed in the engagement despite Russian numerical advantage.', 1808, 10, 27, NULL, NULL, NULL, 'day', '27 October 1808', 41, 'https://en.wikipedia.org/wiki/Battle_of_Koljonvirta'),
  ('Q3362340', 'Battle of Vaasa', 'The Battle of Vaasa was fought between the Kingdom of Sweden and the Russian Empire during the Finnish War (1808-1809). While the Swedish army was celebrating its victory at Nykarleby, another Swedish force, led by Johan Bergenstråhle, landed at Vaasa.', 1808, 6, 25, 1808, 6, 26, 'day', '25 June 1808 – 26 June 1808', 34, 'https://en.wikipedia.org/wiki/Battle_of_Vaasa'),
  ('Q2091915', 'Battle of Bomarsund', 'The Battle of Bomarsund, in August 1854, took place during the Åland War, which was part of the Crimean War, when an Anglo-French expeditionary force besieged, captured, and subsequently destroyed a Russian fortress. It was the only major action of the war to take place at Bomarsund in the Baltic Sea.', 1854, 8, NULL, NULL, NULL, NULL, 'month', 'August 1854', 47, 'https://en.wikipedia.org/wiki/Battle_of_Bomarsund'),
  ('Q1558846', 'Finnish famine of 1866–1868', 'The Finnish famine of 1866–1868 was the last famine in Finland, and (along with the subsequent Swedish famine of 1867–1869) the last major famine in Northern Europe. In Finland, the famine is known as "the great hunger years", or suuret nälkävuodet.', 1867, NULL, NULL, 1869, NULL, NULL, 'year', '1867–1869', 57, 'https://en.wikipedia.org/wiki/Finnish_famine_of_1866%E2%80%931868'),
  ('Q2446816', 'Sveaborg Rebellion', 'The Sveaborg rebellion was an Imperial Russian military mutiny which broke out on the evening of 30 July 1906 amongst the garrison of the coastal fortress of Sveaborg (now known as Suomenlinna) on the coast of Helsinki in the Grand Duchy of Finland. The mutiny was part of the aftermath of the Russian Revolution of 1905, which by summer 1906 had effectively been suppressed in most other regions of the Russian Empire.', 1906, 7, 18, 1906, 7, 20, 'day', '18 July 1906 – 20 July 1906', 45, 'https://en.wikipedia.org/wiki/Sveaborg_rebellion'),
  ('Q27916528', 'Independence of Finland', 'Finland declared its independence on 6 December 1917. The formal Declaration of Independence was only part of the long process leading to the independence of Finland.', 1917, 12, 6, NULL, NULL, NULL, 'day', '6 December 1917', 53, 'https://en.wikipedia.org/wiki/Independence_of_Finland'),
  ('Q211855', 'Finnish Civil War', 'The Finnish Civil War was fought in 1918 for the leadership and control of recently independent Finland (formerly part of Russia) between White Finland and the Finnish Socialist Workers'' Republic (Red Finland). The clashes took place in the context of the national, political, and social turmoil caused by World War I (Eastern Front) in Europe.', 1918, 1, 27, 1918, 5, 15, 'day', '27 January 1918 – 15 May 1918', 78, 'https://en.wikipedia.org/wiki/Finnish_Civil_War'),
  ('Q2043711', 'Battle of Tampere', 'The Battle of Tampere was a 1918 Finnish Civil War battle, fought in Tampere, Finland from 15 March to 6 April between the Whites and the Reds. It is the most famous and deadly of all the Finnish Civil War battles.', 1918, 3, 8, 1918, 4, 6, 'day', '8 March 1918 – 6 April 1918', 58, 'https://en.wikipedia.org/wiki/Battle_of_Tampere'),
  ('Q4411911', 'Battle of Viipuri', 'The Battle of Viipuri was a 1918 Finnish Civil War battle, fought 24–29 April between the Finnish Whites and the Finnish Reds in Viipuri. Together with the Battle of Tampere and Battle of Helsinki, it was one of the three major urban battles of the Finnish Civil War.', 1918, 4, 24, 1918, 4, 29, 'day', '24 April 1918 – 29 April 1918', 41, 'https://en.wikipedia.org/wiki/Battle_of_Viipuri'),
  ('Q11862174', 'Battle of Helsinki', 'The Battle of Helsinki was a 1918 Finnish Civil War battle, fought on 12–13 April by the German troops and Finnish Whites against the Finnish Reds in Helsinki, Finland. Together with the battles of Tampere and Vyborg, it was one of the three major urban battles of the Finnish Civil War.', 1918, 4, 13, NULL, NULL, NULL, 'day', '13 April 1918', 47, 'https://en.wikipedia.org/wiki/Battle_of_Helsinki'),
  ('Q18564908', 'Vyborg massacre', 'The Viipuri massacre was the killing of approximately 360 to 420 Russians in the city of Viipuri (Swedish Viborg, now Vyborg, Russia) during the Finnish Civil War in April–May 1918. The massacre took place during and after the Battle of Viipuri as the White Guards captured the city from the Red Guards.', 1918, 4, 29, NULL, NULL, NULL, 'day', '29 April 1918', 37, 'https://en.wikipedia.org/wiki/Viipuri_massacre'),
  ('Q2996706', 'East Karelian Uprising', 'The East Karelian Uprising (Finnish: itäkarjalaisten kansannousu, Karelian: päivännouzu karjalan kanzannouzu) and the Soviet–Finnish conflict 1921–1922 were an attempt by a group of East Karelian separatists supported by Finland to gain independence from the Russian Soviet Federative Socialist Republic. They were aided by a number of Finnish volunteers, starting from 6 November 1921.', 1921, 11, 6, 1922, 3, 21, 'day', '6 November 1921 – 21 March 1922', 51, 'https://en.wikipedia.org/wiki/East_Karelian_uprising'),
  ('Q4060496', 'Åland convention', 'Åland is demilitarised, meaning that no military forces may be stationed on the islands and that they may not be fortified. Åland is also neutralised, and must therefore be kept outside armed conflict in the event of war.', 1921, 10, 20, NULL, NULL, NULL, 'day', '20 October 1921', 50, 'https://en.wikipedia.org/wiki/%C3%85land_convention'),
  ('Q2112296', 'Finnish prohibition referendum, 1931', 'A referendum on prohibition was held in Finland on 29 and 30 December 1931. Voters were asked whether they approved of the continuation of the prohibition law passed in 1919.', 1931, 12, 30, NULL, NULL, NULL, 'day', '30 December 1931', 43, 'https://en.wikipedia.org/wiki/1931_Finnish_prohibition_referendum'),
  ('Q134949', 'Winter War', 'The Winter War was a war between the Soviet Union and Finland. It began with a Soviet invasion of Finland on 30 November 1939, three months after the outbreak of World War II, and ended three and a half months later with the Moscow Peace Treaty on 13 March 1940.', 1939, 11, 30, 1940, 3, 13, 'day', '30 November 1939 – 13 March 1940', 86, 'https://en.wikipedia.org/wiki/Winter_War'),
  ('Q211211', 'Battle of Kelja', 'The Battle of Kelja, fought from December 25 to December 27, 1939 in and around the village of Kelja (now Portovoe, Priozersky District, Leningrad Oblast, Russia), was a part of the Winter War between Finland and the Soviet Union.', 1939, 12, 25, 1939, 12, 27, 'day', '25 December 1939 – 27 December 1939', 39, 'https://en.wikipedia.org/wiki/Battle_of_Kelja'),
  ('Q477095', 'Battle of Suomussalmi', 'The Battle of Suomussalmi was fought between Finnish and Soviet forces in the Winter War. The action took place from 30 November 1939 to 8 January 1940.', 1939, 12, 7, 1940, 1, 8, 'day', '7 December 1939 – 8 January 1940', 67, 'https://en.wikipedia.org/wiki/Battle_of_Suomussalmi'),
  ('Q639989', 'Battle of Tolvajärvi', 'The Battle of Tolvajärvi ([ˈtol.ʋɑˌjær.ʋi]; Finnish: Tolvajärven–Ägläjärven taistelu, Russian: Битва при Толваярви) began on 12 December 1939 and continued for about a week and a half, between Finland and the Soviet Union. It was the first large offensive victory for the Finns in the Winter War.', 1939, 12, 12, NULL, NULL, NULL, 'day', '12 December 1939', 59, 'https://en.wikipedia.org/wiki/Battle_of_Tolvaj%C3%A4rvi'),
  ('Q715182', 'Battle of Salla', 'The Battle of Salla was fought between Finnish and Soviet troops near Salla in northern Finland during the Winter War. The Soviets had orders to advance through Salla to Kemijärvi and Sodankylä, and from there to Rovaniemi in just two weeks.', 1939, 11, 30, 1940, 2, 28, 'day', '30 November 1939 – 28 February 1940', 55, 'https://en.wikipedia.org/wiki/Battle_of_Salla_(1939)'),
  ('Q695285', 'Moscow Peace Treaty', 'The Moscow Peace Treaty was signed by Finland and the Soviet Union on 12 March 1940, and the ratifications were exchanged on 21 March. It marked the end of the 105-day Winter War, upon which Finland ceded border areas to the Soviet Union.', 1940, 3, 12, NULL, NULL, NULL, 'day', '12 March 1940', 71, 'https://en.wikipedia.org/wiki/Moscow_Peace_Treaty'),
  ('Q751002', 'Battle of Kuhmo', 'The Battle of Kuhmo was a series of skirmishes, mainly between January 28 and March 13, 1940, near the town of Kuhmo during the Soviet-Finnish Winter War. The 54th Soviet Rifle Division was encircled, but was able to hold out until the end of the war.', 1940, 1, 4, 1940, 1, 7, 'day', '4 January 1940 – 7 January 1940', 43, 'https://en.wikipedia.org/wiki/Battle_of_Kuhmo'),
  ('Q2446643', 'Battle of Raate Road', 'The Battle of Raate Road (Finnish: Raatteen tien taistelu) was fought during the Winter War between the Soviet Union and Finland in January 1940, as a part of the Battle of Suomussalmi. On December 7, 1939, the Soviet 163rd Rifle Division captured Suomussalmi, but found itself trapped deep inside Finnish territory, and the Soviet 44th Rifle Division was sent to aid the 163rd.', 1940, 1, 1, 1940, 1, 7, 'day', '1 January 1940 – 7 January 1940', 56, 'https://en.wikipedia.org/wiki/Battle_of_Raate_Road'),
  ('Q2594918', 'Battle of Honkaniemi', 'The Battle of Honkaniemi was fought between Finnish and Soviet forces on 26 February 1940. This battle was notable for being fought by tanks, the only time they were used en masse in combat by Finnish forces in the Winter War.', 1940, 2, 25, 1940, 2, 27, 'day', '25 February 1940 – 27 February 1940', 45, 'https://en.wikipedia.org/wiki/Battle_of_Honkaniemi'),
  ('Q3098938', 'Interim Peace', 'The Interim Peace (Finnish: Välirauha, Swedish: Mellanfreden) was a short period in the history of Finland during the Second World War. The term is used for the time between the Winter War and the Continuation War, lasting a little over 15 months, from 13 March 1940 to 24 June 1941.', 1940, 3, 13, 1941, 6, 25, 'day', '13 March 1940 – 25 June 1941', 45, 'https://en.wikipedia.org/wiki/Interim_Peace'),
  ('Q83055', 'Operation Barbarossa', 'Operation Barbarossa was the invasion of the Soviet Union by Nazi Germany and several of its European Axis allies starting on Sunday, 22 June 1941, during World War II. More than 3.8 million Axis troops invaded the western Soviet Union along a 2,900-kilometer (1,800 mi) front, with the main goal of capturing territory up to a line between Arkhangelsk and Astrakhan, known as the A–A line. The attack became the largest and costliest military offensive in human history, with around 10 million combatants taking part in the opening phase and over 8 million casualties by the end of the operation…', 1941, 6, 22, 1941, 12, 5, 'day', '22 June 1941 – 5 December 1941', 86, 'https://en.wikipedia.org/wiki/Operation_Barbarossa'),
  ('Q122100', 'Continuation War', 'The Continuation War, also known as the Second Soviet–Finnish War, was a conflict fought by Finland and Nazi Germany against the Soviet Union during World War II. It began with a Finnish declaration of war on 25 June 1941 and ended on 19 September 1944 with the Moscow Armistice. The Soviet Union and Finland had previously fought the Winter War from 1939 to 1940, which ended with the Soviet failure to conquer Finland and the Moscow Peace Treaty.', 1941, 6, 25, 1944, 9, 19, 'day', '25 June 1941 – 19 September 1944', 74, 'https://en.wikipedia.org/wiki/Continuation_War'),
  ('Q189266', 'Eastern Front', 'The Eastern Front, also known as the Great Patriotic War, or the German–Soviet War, was a theatre of World War II fought between the European Axis powers and Allies, including the Soviet Union (USSR) and Poland. It encompassed Central Europe, Eastern Europe, Northeast Europe (Baltics), and Southeast Europe (Balkans), and lasted from 22 June 1941 to 9 May 1945.', 1941, 6, 22, 1945, 5, 7, 'day', '22 June 1941 – 7 May 1945', 85, 'https://en.wikipedia.org/wiki/Eastern_Front_(World_War_II)'),
  ('Q384680', 'Battle of Hanko', 'The Battle of Hanko (also known as the Hanko front or the siege of Hanko) was a lengthy series of small battles fought on Hanko Peninsula during the Continuation War between Finland and the Soviet Union in the second half of 1941. As both sides were eager to avoid a major, costly ground battle, fighting took the form of trench warfare, with artillery exchanges, sniping, patrol clashes, and small amphibious operations performed in the surrounding archipelago.', 1941, 6, 22, 1941, 12, 2, 'day', '22 June 1941 – 2 December 1941', 47, 'https://en.wikipedia.org/wiki/Battle_of_Hanko_(1941)'),
  ('Q4352802', 'Battle of Bengtskär', 'The Battle of Bengtskär was an amphibious landing action fought between Finnish and Soviet forces on 26 July 1941 during the Continuation War.', 1941, 7, 26, NULL, NULL, NULL, 'day', '26 July 1941', 39, 'https://en.wikipedia.org/wiki/Battle_of_Bengtsk%C3%A4r'),
  ('Q154940', 'Lapland War', 'During World War II, the Lapland War saw fighting between Finland and Nazi Germany – effectively from September to November 1944 – in Finland''s northernmost region, Lapland. Though the Finns and the Germans had been fighting together against the Soviet Union since 1941 during the Continuation War (1941–1944), peace negotiations between the Finnish government and the Allies of World War II had been conducted intermittently during 1943–1944, but no agreement had been reached.', 1944, 9, 15, 1945, 4, 25, 'day', '15 September 1944 – 25 April 1945', 75, 'https://en.wikipedia.org/wiki/Lapland_War'),
  ('Q697680', 'Battle of Tali-Ihantala', 'The Battle of Tali–Ihantala (June 25 to July 9, 1944) was part of the Finnish-Soviet Continuation War (1941–1944), which occurred during World War II. The battle was fought between Finnish forces—using war materiel provided by Germany—and Soviet forces. To date, it is the largest battle in the history of the Nordic countries.', 1944, 6, 25, 1944, 7, 9, 'day', '25 June 1944 – 9 July 1944', 58, 'https://en.wikipedia.org/wiki/Battle_of_Tali%E2%80%93Ihantala'),
  ('Q705222', 'Petsamo–Kirkenes Offensive', 'The Petsamo–Kirkenes offensive was a major military offensive during World War II, mounted by the Red Army against the Wehrmacht in 1944 in the Petsamo region, ceded to the Soviet Union by Finland in accordance with the Moscow Armistice, and Norway. The offensive defeated the Wehrmacht''s forces in the Arctic, driving them back into Norway, and was called the "Tenth Shock" by Stalin.', 1944, 10, 7, 1944, 10, 31, 'day', '7 October 1944 – 31 October 1944', 60, 'https://en.wikipedia.org/wiki/Petsamo%E2%80%93Kirkenes_offensive'),
  ('Q1321586', 'Moscow Armistice', 'The Moscow Armistice was signed between Finland on one side and the Soviet Union and United Kingdom on the other side on 19 September 1944, ending the Continuation War. The Armistice restored the Moscow Peace Treaty of 1940, with a number of modifications.', 1944, 9, 19, NULL, NULL, NULL, 'day', '19 September 1944', 64, 'https://en.wikipedia.org/wiki/Moscow_Armistice'),
  ('Q2354840', 'Battle of Ilomantsi', 'The Battle of Ilomantsi (Finnish: Ilomantsin taistelu) was a part of the Svir–Petrozavodsk Offensive of the Continuation War (1941–1944). It was fought from 26 July to 13 August 1944, between Finland and the Soviet Union in an area roughly 40 kilometers wide and 30 kilometers deep, near the Finnish-Soviet border, close to the Finnish village of Ilomantsi, in North Karelia.', 1944, 7, 26, 1944, 8, 13, 'day', '26 July 1944 – 13 August 1944', 51, 'https://en.wikipedia.org/wiki/Battle_of_Ilomantsi_(1944)'),
  ('Q2663546', 'Battle of Vuosalmi', 'The Battle of Vuosalmi (also known as the Battle of Äyräpää-Vuosalmi) – the main bulk of it – lasted from July 4 to July 17, 1944. It was fought during the Continuation War (1941–1944), a part of World War II, between Finland and the Soviet Union.', 1944, NULL, NULL, 1944, 7, 15, 'year', '1944', 43, 'https://en.wikipedia.org/wiki/Battle_of_Vuosalmi'),
  ('Q2756240', 'Battle of Tienhaara', 'The Battle of Tienhaara was a part of Continuation War between Finland and the Soviet Union fought north of Viipuri on June 22, 1944, after the Red Army had captured Viipuri. Having lost Viipuri, the Finns concentrated their defense to the Tienhaara region which offered favourable area for defense with nearby waterway cutting the already narrow battlefield into several islands.', 1944, 6, 22, NULL, NULL, NULL, 'day', '22 June 1944', 43, 'https://en.wikipedia.org/wiki/Battle_of_Tienhaara'),
  ('Q3269671', 'Battle of Rovaniemi', 'The Battle of Rovaniemi was an event during the 1944 Lapland War. The actual fighting between the components of the Finnish Armoured Division and Finnish 3rd Division against the troops of the German Twentieth Mountain Army took place at the vicinity of the town of Rovaniemi.', 1944, NULL, NULL, 1944, 10, 13, 'year', '1944', 39, 'https://en.wikipedia.org/wiki/Battle_of_Rovaniemi'),
  ('Q3752815', 'Battle of Tornio', 'The Battle of Tornio (October 1–8, 1944) was the first major engagement between Nazi Germany and Finland in the Lapland War; although hostilities had already begun elsewhere (see Tanne Ost).', 1944, NULL, NULL, 1944, 10, 8, 'year', '1944', 39, 'https://en.wikipedia.org/wiki/Battle_of_Tornio'),
  ('Q322943', 'Paris Peace Treaties', 'The Paris Peace Treaties (French: Traités de Paris) were signed on 10 February 1947 following the end of World War II in 1945. The Paris Peace Conference lasted from 29 July until 15 October 1946.', 1947, 2, 10, NULL, NULL, NULL, 'day', '10 February 1947', 72, 'https://en.wikipedia.org/wiki/Paris_Peace_Treaties%2C_1947'),
  ('Q1417787', 'Finno-Soviet Treaty of 1948', 'The Agreement of Friendship, Cooperation, and Mutual Assistance of 1948, also known as the YYA Treaty from the Finnish Ystävyys-, yhteistyö- ja avunantosopimus (YYA-sopimus) (Swedish: Vänskaps-, samarbets- och biståndsavtalet (VSB-avtalet)), was the basis for Finno–Soviet relations from 1948 to 1992. It was the main instrument in implementing the Finnish policy called Paasikivi–Kekkonen doctrine.', 1948, 4, 6, NULL, NULL, NULL, 'day', '6 April 1948', 56, 'https://en.wikipedia.org/wiki/Finno-Soviet_Treaty_of_1948'),
  ('Q381183', 'Aero Flight 311', 'Aero Flight 311, often referred to as the Kvevlax air disaster, was a scheduled domestic passenger flight operated by Aero O/Y (now Finnair) between Kronoby and Vaasa in Finland. The aircraft, a Douglas DC-3, crashed in the municipality Kvevlax (Finnish: Koivulahti), nowadays part of Korsholm (Finnish: Mustasaari) on 3 January 1961, killing all twenty-five people on board.', 1961, 1, 3, NULL, NULL, NULL, 'day', '3 January 1961', 45, 'https://en.wikipedia.org/wiki/Aero_Flight_311'),
  ('Q5493470', 'Lapua Cartridge Factory Explosion', 'The Lapua Cartridge Factory explosion (Finnish: Lapuan patruunatehtaan räjähdys) was an industrial disaster that occurred at the State Cartridge Factory in Lapua, Finland on 13 April 1976. It caused the deaths of 40 workers, while 60 people were injured.', 1976, 4, 13, NULL, NULL, NULL, 'day', '13 April 1976', 34, 'https://en.wikipedia.org/wiki/Lapua_Cartridge_Factory_explosion'),
  ('Q600836', 'Jokela school shooting', 'On 7 November 2007, a mass shooting occurred at Jokela High School in the town of Jokela, Tuusula, Finland. The gunman, 18-year-old Pekka-Eric Auvinen, entered the school that morning armed with a semi-automatic pistol.', 2007, 11, 7, NULL, NULL, NULL, 'day', '7 November 2007', 70, 'https://en.wikipedia.org/wiki/Jokela_school_shooting'),
  ('Q15991234', 'Treaty Establishing the European Stability Mechanism', 'The Treaty Establishing the European Stability Mechanism was signed by the member states of the eurozone to found the European Stability Mechanism (ESM), an international organisation located in Luxembourg, to act as a permanent source of financial assistance for member states in financial difficulty, with a maximum lending capacity of €500 billion. It replaced two earlier temporary EU funding programmes: the European Financial Stability Facility (EFSF) and the European Financial Stabilisation Mechanism (EFSM).', 2012, 2, 2, NULL, NULL, NULL, 'day', '2 February 2012', 34, 'https://en.wikipedia.org/wiki/Treaty_establishing_the_European_Stability_Mechanism'),
  ('Q37150759', '2017 Turku attack', 'On 18 August 2017, a mass stabbing took place in Turku, Finland. Two people were killed and eight others were injured before the perpetrator, 22-year-old Abderrahman Bouanane, was detained.', 2017, 8, 18, NULL, NULL, NULL, 'day', '18 August 2017', 63, 'https://en.wikipedia.org/wiki/2017_Turku_attack'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe');
